function transform(input) { 
    var kpiProperties = [
        'sam.foundation.current.users.kpi',
        'sam.foundation.current.company.kpi',
        'sam.foundation.current.location.kpi',
        'sam.foundation.current.costcenter.kpi',
        'sam.foundation.current.businessunit.kpi',
        'sam.foundation.current.department.kpi',
        'sam.implementation.healthcheck',
        'sam.implementation.euc',
        'sam.implementation.servers',
        'sam.current.installation.kpi',
        'sam.current.subscription.kpi',
        'sam.current.entitlement.kpi',
        'sam.current.contract.kpi',
        'sam.current.discoverymodel.kpi',
        'sam.current.softwaremodel.kpi',
        "sam.properties"
    ];

    function fetchKPIs(propertyName) {
        var kpis = [];
        var propertyValue = gs.getProperty(propertyName);
        if (propertyValue) {
            try {
                kpis = JSON.parse(propertyValue);
            } catch (e) {
                gs.error("Error parsing " + propertyName + ": " + e.message);
            }
        }
        return kpis;
    }

    function getTasksByProperty() {
        var result = [];

        for (var i = 0; i < kpiProperties.length; i++) {
            var propertyName = kpiProperties[i];
            var kpis = fetchKPIs(propertyName);
            var additionalFields = [];
            var hasFoundTasks = false;

            for (var j = 0; j < kpis.length; j++) {
                var kpi = kpis[j];

                if (kpi.description) {
                    var taskGr = new GlideRecord('samp_sp_vb_task');
                    taskGr.addEncodedQuery('stateNOT IN-5,3,7');
                    taskGr.addQuery('description', kpi.description);
                    taskGr.addQuery('short_description', kpi.kpi);
                    taskGr.query();

                    while (taskGr.next()) {
                        hasFoundTasks = true;
                        additionalFields.push({
                            sys_id: taskGr.getUniqueValue(),
                            description: taskGr.getValue("description"),
                            short_description: taskGr.getValue("short_description"),
                            task_number: taskGr.getValue("number"),
                            state: taskGr.getDisplayValue('state'),
                            assigned_to: taskGr.getDisplayValue('assigned_to')
                        });
                    }
                }
            }

            // Always add an entry to the result array, regardless of whether tasks were found
            result.push({
                additionalFields: additionalFields
            });
        }

        gs.log('tasks available:'+JSON.stringify(result,null,2));
        return result;
    }

    return getTasksByProperty();
}
